<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';
$term=trim((string)($_GET['q']??''));$results=[];$categories=[];$error='';
try{$pdo=db();$categories=$pdo->query("SELECT id,name,slug FROM categories WHERE is_active=1 AND compliance_status='approved' ORDER BY sort_order,name")->fetchAll();if($term!==''){$q=$pdo->prepare("SELECT p.id,p.name,p.slug,p.price,p.stock_quantity-p.reserved_quantity available,p.short_description,(SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY is_primary DESC,sort_order LIMIT 1) image_path FROM products p JOIN categories c ON c.id=p.category_id WHERE p.status='active' AND p.compliance_status='approved' AND c.is_active=1 AND c.compliance_status='approved' AND (p.name LIKE ? OR p.sku LIKE ? OR p.short_description LIKE ?) ORDER BY p.is_featured DESC,p.created_at DESC LIMIT 48");$like='%'.$term.'%';$q->execute([$like,$like,$like]);$results=$q->fetchAll();}}catch(Throwable $e){error_log($e->getMessage());$error='تعذر تنفيذ البحث حالياً.';}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>البحث | الفخامة</title><link rel="stylesheet" href="assets/css/store.css"><style>.search-form{display:flex;gap:8px;margin:20px 0}.search-form input{flex:1;min-width:0;background:#111;color:white;border:1px solid #49371c;border-radius:25px;padding:12px 18px;font:inherit}</style></head><body><header class="site-header"><div class="container nav-wrap"><a class="brand" href="./"><span class="brand-mark">ف</span><span><strong>الفخامة</strong><small>AL FAKHAMAH</small></span></a><a class="btn btn-outline" href="cart.php">السلة</a></div></header><main class="section"><div class="container"><span class="eyebrow">اكتشف مجموعتنا</span><h1>البحث عن المنتجات</h1><form class="search-form"><input name="q" value="<?=e($term)?>" placeholder="اكتب اسم المنتج أو رمزه..." minlength="2"><button class="btn btn-gold">بحث</button></form><?php if($error):?><div class="notice"><?=e($error)?></div><?php elseif($term===''):?><div class="empty-state"><h3>ما الذي تبحث عنه؟</h3><p>أدخل اسم المنتج أو رمز SKU للعثور عليه.</p></div><?php elseif(!$results):?><div class="empty-state"><h3>لم نعثر على نتائج</h3><p>جرّب كلمة بحث مختلفة.</p></div><?php else:?><p>نتائج البحث عن: <strong><?=e($term)?></strong> (<?=count($results)?>)</p><div class="product-grid"><?php foreach($results as $p):?><article class="product-card"><a class="product-image" href="product.php?slug=<?=rawurlencode($p['slug'])?>"><?php if($p['image_path']):?><img loading="lazy" src="<?=e($p['image_path'])?>" alt="<?=e($p['name'])?>"><?php else:?><span class="image-placeholder">الفخامة</span><?php endif;?></a><div class="product-info"><h3><?=e($p['name'])?></h3><p><?=e($p['short_description'])?></p><div class="product-bottom"><strong><?=number_format((float)$p['price'],2)?> ر.س</strong><span class="<?=((int)$p['available']>0?'available':'unavailable')?>"><?=((int)$p['available']>0?'متوفر':'غير متوفر')?></span></div><a class="btn btn-outline" href="product.php?slug=<?=rawurlencode($p['slug'])?>">التفاصيل</a></div></article><?php endforeach;?></div><?php endif;?></div></main></body></html>